CREATE TABLE m02.daily_task_number(factory_id text NOT NULL,day char(8) NOT NULL,value bigint NOT NULL,PRIMARY KEY(factory_id,day));
ALTER TABLE m02.inspection_task ALTER COLUMN planned_length_m DROP NOT NULL;
ALTER TABLE m02.inspection_task DROP CONSTRAINT inspection_task_state_check;
ALTER TABLE m02.inspection_task ADD CHECK(state IN('CREATED','RUNNING','ENDED','CANCELLED'));
ALTER TABLE m02.inspection_task ADD COLUMN creation_source text NOT NULL DEFAULT 'MANUAL' CHECK(creation_source IN('MANUAL','AUTO'));
ALTER TABLE m02.inspection_task ADD COLUMN reported_length_m numeric(24,10);
ALTER TABLE m02.inspection_task ADD COLUMN length_status text NOT NULL DEFAULT 'UNKNOWN' CHECK(length_status IN('UNKNOWN','REPORTED_UNVERIFIED','COUNTER_CHANGED'));
ALTER TABLE m02.cable_spool ADD COLUMN version bigint NOT NULL DEFAULT 1;
ALTER TABLE m02.cable_spool ADD COLUMN canonical_spool_id text REFERENCES m02.cable_spool(id);
CREATE TABLE m02.batch_plan(id text PRIMARY KEY,factory_id text NOT NULL,name varchar(128) NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE m02.plan_item(id text PRIMARY KEY,plan_id text NOT NULL REFERENCES m02.batch_plan(id),ordinal integer NOT NULL,request jsonb NOT NULL,task_id text UNIQUE REFERENCES m02.inspection_task(id),last_error jsonb,removed_at timestamptz,remove_reason text,UNIQUE(plan_id,ordinal));
CREATE TABLE m02.discovery_profile(factory_id text NOT NULL,device_id text NOT NULL,enabled boolean NOT NULL DEFAULT false,specification_id text NOT NULL,recipe_version_id text,version bigint NOT NULL DEFAULT 1,PRIMARY KEY(factory_id,device_id));
CREATE TABLE m02.material_identity(factory_id text NOT NULL,data_environment text NOT NULL,material_ref text NOT NULL,spool_id text NOT NULL REFERENCES m02.cable_spool(id),PRIMARY KEY(factory_id,data_environment,material_ref));
CREATE TABLE m02.production_encounter(factory_id text NOT NULL,device_id text NOT NULL,encounter_id text NOT NULL,task_id text NOT NULL UNIQUE REFERENCES m02.inspection_task(id),enter_payload jsonb NOT NULL,exit_payload jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(factory_id,device_id,encounter_id));
CREATE TABLE m02.production_event(factory_id text NOT NULL,device_id text NOT NULL,event_id text NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(factory_id,device_id,event_id));
CREATE INDEX task_search_recent ON m02.inspection_task(factory_id,created_at DESC,id);
CREATE INDEX plan_recent ON m02.batch_plan(factory_id,created_at DESC,id);
GRANT SELECT,INSERT,UPDATE ON m02.daily_task_number,m02.batch_plan,m02.plan_item,m02.discovery_profile,m02.material_identity,m02.production_encounter TO hy_runtime;
GRANT SELECT,INSERT ON m02.production_event TO hy_runtime;
